which node && node -e "
const fs = require('fs');
// Read the db file and search for PROD-73FAB4
const buf = fs.readFileSync('/workspace/world.db');
const str = buf.toString('utf-8');
const idx = str.indexOf('PROD-73FAB4');
if (idx >= 0) {
  // Print surrounding context
  const start = Math.max(0, idx - 500);
  const end = Math.min(str.length, idx + 500);
  const context = buf.slice(start, end).toString('utf-8');
  console.log('Found at index', idx);
  console.log('Context:', JSON.stringify(context));
}
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables);
for (const t of tables) {
  const info = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\n--- ' + t.name + ' ---');
  info.forEach(c => console.log(c));
}
db.close();
" 2>&1 || echo "---"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const info = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\n--- ' + t.name + ' ---');
  info.forEach(c => console.log(c.name, c.type));
}
db.close();
"

